cards.solution:
const daftar = [{ id: 1, teks: "Rapat", selesai: true }];
function tampilkanTugas(daftar) {
  for (const tugas of daftar) {
    const status = tugas.selesai ? "Selesai" : "Belum";
    console.log(`${tugas.id}. ${tugas.teks} (${status})`);
  }
}
tampilkanTugas(daftar);
